package com.lore.zzal.pet.receipt;
import com.lore.zzal.pet.*;import com.lore.zzal.pet.dto.PetRequests;import com.lore.zzal.attendance.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.orm.jpa.*;import org.springframework.orm.jpa.vendor.HibernateJpaVendorAdapter;
import org.springframework.data.jpa.repository.support.JpaRepositoryFactory;import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.transaction.interceptor.TransactionInterceptor;import org.springframework.transaction.annotation.AnnotationTransactionAttributeSource;
import org.springframework.aop.framework.ProxyFactory;import org.springframework.test.util.ReflectionTestUtils;
import java.time.Instant;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;
import static org.mockito.Mockito.*;import static org.assertj.core.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="LORE_CARE_ALL_DB_URL",matches="jdbc:postgresql://127\\.0\\.0\\.1:55420/lore_care_receipt_[0-9_]+_test")
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class CareAllPostgresTest {
 final Instant now=Instant.parse("2026-10-18T03:00:00Z");jakarta.persistence.EntityManagerFactory emf;jakarta.persistence.EntityManager em;JpaTransactionManager tm;TransactionTemplate tx;JdbcTemplate jdbc;ZzalPetRepository owners;ActionReceiptRepository receipts;Long petId;AtomicInteger calls=new AtomicInteger();boolean failAfterCare,failAfterSave;
 @BeforeAll void schema(){var ds=new DriverManagerDataSource(System.getenv("LORE_CARE_ALL_DB_URL"),System.getenv("LORE_TEST_DB_USERNAME"),System.getenv("LORE_TEST_DB_PASSWORD"));jdbc=new JdbcTemplate(ds);org.flywaydb.core.Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();var f=new LocalContainerEntityManagerFactoryBean();f.setDataSource(ds);f.setPackagesToScan("com.lore.zzal.pet");f.setJpaVendorAdapter(new HibernateJpaVendorAdapter());f.setJpaPropertyMap(Map.of("hibernate.hbm2ddl.auto","validate","hibernate.physical_naming_strategy","org.hibernate.boot.model.naming.PhysicalNamingStrategySnakeCaseImpl"));f.afterPropertiesSet();emf=f.getObject();em=SharedEntityManagerCreator.createSharedEntityManager(emf);tm=new JpaTransactionManager(emf);tx=new TransactionTemplate(tm);var factory=new JpaRepositoryFactory(em);owners=factory.getRepository(ZzalPetRepository.class);receipts=factory.getRepository(ActionReceiptRepository.class);}
 @AfterAll void close(){if(emf!=null)emf.close();}
 @BeforeEach void seed(){calls.set(0);failAfterCare=false;failAfterSave=false;petId=tx.execute(s->{var p=ZzalPet.draft(900101L,"images/synthetic/care-all",now.minusSeconds(100));ReflectionTestUtils.setField(p,"createdAt",now);ReflectionTestUtils.setField(p,"updatedAt",now);ReflectionTestUtils.setField(p,"phase",PetPhase.ALIVE);ReflectionTestUtils.setField(p,"hatchedAt",now);ReflectionTestUtils.setField(p,"tutorialStep",99);ReflectionTestUtils.setField(p,"fullness",0);ReflectionTestUtils.setField(p,"food",3);ReflectionTestUtils.setField(p,"trash",4);em.persist(p);em.flush();return p.getId();});}
 @SuppressWarnings("unchecked") <T>T proxy(T target){var p=new ProxyFactory(target);p.setProxyTargetClass(true);p.addAdvice(new TransactionInterceptor(tm,new AnnotationTransactionAttributeSource()));return (T)p.getProxy();}
 CareActionRequestService service(){
  PetService target=mock(PetService.class,CALLS_REAL_METHODS);var pieces=mock(com.lore.zzal.piece.PieceService.class);ReflectionTestUtils.setField(target,"pieceService",pieces);
  var own=mock(CustomMotionOwnershipService.class);when(own.owned(anyLong(),anyLong())).thenAnswer(i->{if(failAfterCare){em.flush();throw new com.lore.common.exception.BusinessException(com.lore.common.exception.ErrorCode.ZZAL_CARE_NOT_NEEDED);}return List.of(new OwnedCustomMotion("custom:a",10L,1,"합성","합성","pet",false,"images/synthetic/a.webp",null,"pet",1,true,true,"CUSTOM"));});target.setCareMotionRotationService(new CareMotionRotationService(own));
  doAnswer(i->{calls.incrementAndGet();var pet=owners.findByIdForUpdate(petId).orElseThrow();if(pet.isTraveling())throw new com.lore.common.exception.BusinessException(com.lore.common.exception.ErrorCode.ZZAL_TRAVELING);return pet;}).when(target).alive(anyLong(),anyLong(),any());
  doAnswer(i->{var pet=owners.findByIdForUpdate(petId).orElseThrow();ReflectionTestUtils.setField(pet,"settledAt",now);return pet;}).when(target).refresh(anyLong(),anyLong(),any());
  doAnswer(i->{((Runnable)i.getArgument(1)).run();return new PetService.Action(i.getArgument(0),List.of());}).when(target).withUnlockDiff(any(),any());
  PetService pets=proxy(target);var repo=mock(ActionReceiptRepository.class);when(repo.findByPetIdAndRequestId(any(),any())).thenAnswer(i->receipts.findByPetIdAndRequestId(i.getArgument(0),i.getArgument(1)));when(repo.saveAndFlush(any())).thenAnswer(i->{var saved=receipts.saveAndFlush(i.getArgument(0));if(failAfterSave)throw new IllegalStateException("synthetic failure after receipt/effect flush");return saved;});
  var delivery=proxy(new CareActionDeliveryService(pets,owners,repo,tools.jackson.databind.json.JsonMapper.builder().build()));var boundary=proxy(new ProtectedCareActionBoundary(pets,delivery));return new CareActionRequestService(pets,boundary);
 }
 PetRequests.Care request(CareAction a,UUID id){return new PetRequests.Care(a,null,id);}
 ZzalPet read(){return tx.execute(s->owners.findById(petId).orElseThrow());}
 int count(){return jdbc.queryForObject("select count(*) from zzal_action_receipt where pet_id=?",Integer.class,petId);}
 void change(java.util.function.Consumer<ZzalPet> mutation){tx.executeWithoutResult(s->mutation.accept(owners.findById(petId).orElseThrow()));}
 @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.EnumSource(CareAction.class)
 void sixCareKindsHaveOneAtomicOccurrence(CareAction action){if(action==CareAction.MEDICINE)change(p->{ReflectionTestUtils.setField(p,"sickKind",SickKind.NATURAL);ReflectionTestUtils.setField(p,"sickSince",now.minusSeconds(1));});var service=service();var id=UUID.randomUUID();var first=service.care(900101L,petId,request(action,id),now);var replay=service.care(900101L,petId,request(action,id),now);assertThat(replay.motionPlayback()).isEqualTo(first.motionPlayback());assertThat(calls.get()).isEqualTo(1);assertThat(count()).isEqualTo(1);assertThat(jdbc.queryForObject("select action_kind from zzal_action_receipt where pet_id=?",String.class,petId)).isEqualTo("CARE_"+action.name());var p=read();switch(action){case FEED->assertThat(p.getFeeds()).isEqualTo(1);case SNACK->assertThat(p.getSnacks()).isEqualTo(1);case PET->assertThat(p.getPets()).isEqualTo(1);case CLEAN->assertThat(p.getCleans()).isEqualTo(1);case BATH->assertThat(p.getBathCount()).isEqualTo(1);case MEDICINE->assertThat(p.isSick()).isFalse();}if(action!=CareAction.PET)assertThat(p.careMotionCursor("PET")).isNull();}
 @Test void businessFailureAfterMutationRollsBackEffectButKeepsCommittedSettlement(){failAfterCare=true;var service=service();assertThatThrownBy(()->service.care(900101L,petId,request(CareAction.PET,UUID.randomUUID()),now)).isInstanceOf(com.lore.common.exception.BusinessException.class);var p=read();assertThat(p.getPets()).isZero();assertThat(p.careMotionCursor("PET")).isNull();assertThat(p.getSettledAt()).isEqualTo(now);assertThat(count()).isZero();}
 @Test void flushedReceiptFailureRollsBackEverythingExceptSettlement(){failAfterSave=true;var service=service();assertThatThrownBy(()->service.care(900101L,petId,request(CareAction.CLEAN,UUID.randomUUID()),now)).isInstanceOf(IllegalStateException.class);var p=read();assertThat(p.getCleans()).isZero();assertThat(p.getTrash()).isEqualTo(4);assertThat(p.getSettledAt()).isEqualTo(now);assertThat(count()).isZero();}
 @Test void introNoopCreatesNoReceipt(){change(p->p.devSetFirstIntro(4,FirstIntro.Step.CLEAN,now));var service=service();var result=service.care(900101L,petId,new PetRequests.Care(CareAction.FEED,FirstIntro.Step.FEED,UUID.randomUUID()),now);assertThat(result.performed()).isFalse();assertThat(count()).isZero();assertThat(read().getPets()).isZero();assertThat(read().careMotionCursor("PET")).isNull();}
 @Test void rejectionKeepsSettlementWithoutReceipt(){change(p->ReflectionTestUtils.setField(p,"trash",0));var service=service();assertThatThrownBy(()->service.care(900101L,petId,request(CareAction.CLEAN,UUID.randomUUID()),now)).isInstanceOf(com.lore.common.exception.BusinessException.class);assertThat(read().getSettledAt()).isEqualTo(now);assertThat(count()).isZero();}
 @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(booleans={false,true})
 void ambientCallerWithOrWithoutPetLockFailsBeforeSettlement(boolean locked){var service=service();assertThatThrownBy(()->tx.execute(s->{if(locked)owners.findByIdForUpdate(petId).orElseThrow();return service.care(900101L,petId,request(CareAction.PET,UUID.randomUUID()),now);})).isInstanceOf(org.springframework.transaction.IllegalTransactionStateException.class);assertThat(read().getPets()).isZero();assertThat(read().getSettledAt()).isNotEqualTo(now);assertThat(count()).isZero();assertThat(calls.get()).isZero();}
 @Test void legacyNullStillJoinsAmbientTransaction(){var service=service();assertThatThrownBy(()->tx.execute(s->{service.care(900101L,petId,new PetRequests.Care(CareAction.PET),now);throw new IllegalStateException("outer rollback");})).isInstanceOf(IllegalStateException.class);assertThat(read().getPets()).isZero();assertThat(count()).isZero();}
 @Test void concurrentProtectedRequestsConsumePetAndCursorOnce()throws Exception{var service=service();var id=UUID.randomUUID();var start=new java.util.concurrent.CountDownLatch(1);var pool=java.util.concurrent.Executors.newFixedThreadPool(2);try{java.util.concurrent.Callable<CareMotionPlayback> call=()->{start.await();return service.care(900101L,petId,request(CareAction.PET,id),now).motionPlayback();};var a=pool.submit(call);var b=pool.submit(call);start.countDown();assertThat(a.get(8,java.util.concurrent.TimeUnit.SECONDS)).isEqualTo(b.get(8,java.util.concurrent.TimeUnit.SECONDS));assertThat(read().getPets()).isEqualTo(1);assertThat(read().careMotionCursor("PET").id()).isEqualTo("base");assertThat(count()).isEqualTo(1);}finally{start.countDown();pool.shutdownNow();}}
 @Test void legacyPetReceiptIsReadWithoutHashRewrite(){var id=UUID.randomUUID();var req=request(CareAction.PET,id);tx.executeWithoutResult(s->receipts.saveAndFlush(new ActionReceipt(petId,id,CareActionDeliveryService.requestHash(req),"{\"justUnlocked\":[],\"justHealed\":false,\"motionPlayback\":null}",now)));var service=service();service.care(900101L,petId,req,now);assertThat(calls.get()).isZero();assertThat(count()).isEqualTo(1);assertThat(read().getPets()).isZero();}

 @Test void metadataDistinguishesAppliedReplayAndLegacyWithoutChangingSavedOutcome(){var service=service();var id=UUID.randomUUID();var req=request(CareAction.PET,id);var first=service.careResult(900101L,petId,req,now);assertThat(first.careReceipt()).isEqualTo(new CareReceipt(id,CareAction.PET,CareReceipt.Status.APPLIED));var saved=jdbc.queryForObject("select result_json::text from zzal_action_receipt where pet_id=?",String.class,petId);var replay=service.careResult(900101L,petId,req,now);assertThat(replay.careReceipt()).isEqualTo(new CareReceipt(id,CareAction.PET,CareReceipt.Status.REPLAYED));assertThat(read().getPets()).isEqualTo(1);assertThat(jdbc.queryForObject("select result_json::text from zzal_action_receipt where pet_id=?",String.class,petId)).isEqualTo(saved);assertThat(service.careResult(900101L,petId,new PetRequests.Care(CareAction.PET),now).careReceipt()).isNull();}
 @Test void metadataNoopDoesNotCreateAnOccurrence(){change(p->p.devSetFirstIntro(4,FirstIntro.Step.CLEAN,now));var id=UUID.randomUUID();var result=service().careResult(900101L,petId,new PetRequests.Care(CareAction.FEED,FirstIntro.Step.FEED,id),now);assertThat(result.careReceipt()).isEqualTo(new CareReceipt(id,CareAction.FEED,CareReceipt.Status.NO_OP));assertThat(result.action().performed()).isFalse();assertThat(count()).isZero();}
}
